TLM.f("Tempora/Quad1-6",{"officium":"Sabbato Quattuor Temporum Quadrageismæ","rule":["no Gloria","Suffragium=Sanctorum;Vivis;;","Super popul","celebranda aut forma longior aut forma brevior","LectioL5"],"ruleInherited":["no Gloria","Credo","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;"],"fallback":"Tempora/Quad1-0","sections":{"Introitus":[{"k":"ref","la":"Ps 87:3"},{"k":"text","la":"Intret orátio mea in conspéctu tuo: inclína aurem tuam ad precem meam, Dómine."},{"k":"ref","la":"Ps 87:2"},{"k":"text","la":"Dómine, Deus salútis meæ: in die clamávi, et nocte coram te."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Intret orátio mea in conspéctu tuo: inclína aurem tuam ad precem meam, Dómine."}],"Oratio":[{"k":"text","la":"Pópulum tuum, quǽsumus, Dómine, propítius réspice: atque ab eo flagélla tuæ iracúndiæ cleménter avérte."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Thessalonicénses"},{"k":"ref","la":"1 Thess 5:14-23"},{"k":"text","la":"Fratres: Rogámus vos, corrípite inquiétos, consolámini pusillánimes, suscípite infirmos, patiéntes estóte ad omnes. Vidéte, ne quis malum pro malo alícui reddat: sed semper quod bonum est sectámini in ínvicem, et in omnes. Semper gaudéte. Sine intermissióne oráte. In ómnibus grátias ágite: hæc est enim volúntas Dei in Christo Jesu in ómnibus vobis. Spíritum nolíte exstínguere. Prophetías nolíte spérnere. Omnia autem probáte: quod bonum est tenéte. Ab omni spécie mala abstinéte vos. Ipse autem Deus pacis sanctíficet vos per ómnia: ut ínteger spíritus vester, et ánima, et corpus sine queréla, in advéntu Dómini nostri Jesu Christi servétur."}],"Graduale":[{"k":"ref","la":"Ps 116:1-2"},{"k":"text","la":"Laudáte Dóminum, omnes gentes: et collaudáte eum, omnes pópuli."},{"k":"text","la":"Quóniam confirmáta est super nos misericórdia ejus: et véritas Dómini manet in ætérnum.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 17:1-9"},{"k":"text","la":"In illo témpore: Assúmpsit Jesus Petrum, et Jacóbum, et Joánnem fratrem ejus, et duxit illos in montem excélsum seórsum: et transfigurátus est ante eos. Et resplénduit fácies ejus sicut sol: vestiménta autem ejus facta sunt alba sicut nix. Et ecce, apparuérunt illis Móyses et Elías cum eo loquéntes. Respóndens autem Petrus, dixit ad Jesum: Dómine, bonum est nos hic esse: si vis, faciámus hic tria tabernácula, tibi unum, Móysi unum et Elíæ unum. Adhuc eo loquénte, ecce, nubes lúcida obumbrávit eos. Et ecce vox de nube, dicens: Hic est Fílius meus diléctus, in quo mihi bene complácui: ipsum audíte. Et audiéntes discípuli, cecidérunt in fáciem suam, et timuérunt valde. Et accéssit Jesus, et tétigit eos, dixítque eis: Súrgite, et nolíte timére. Levántes autem óculos suos, néminem vidérunt nisi solum Jesum. Et descendéntibus illis de monte, præcépit eis Jesus, dicens: Némini dixéritis visiónem, donec Fílius hóminis a mórtuis resúrgat."}],"Offertorium":[{"k":"ref","la":"Ps 87:2-3"},{"k":"text","la":"Dómine, Deus salútis meæ, in die clamávi et nocte coram te: intret orátio mea in conspéctu tuo, Dómine."}],"Secreta":[{"k":"text","la":"Præséntibus sacrifíciis, quǽsumus, Dómine, jejúnia nostra sanctífica: ut, quod observántia nostra profitétur extrínsecus, intérius operétur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 7:2"},{"k":"text","la":"Dómine, Deus meus, in te sperávi: líbera me ab ómnibus persequéntibus me, et éripe me."}],"Postcommunio":[{"k":"text","la":"Sanctificatiónibus tuis, omnípotens Deus, et vítia nostra curéntur, et remédia nobis ætérna provéniant."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Fidéles tuos, Deus, benedíctio desideráta confírmet: quæ eos et a tua voluntáte numquam fáciat discrepáre, et tuis semper indúlgeat benefíciis gratulári."},{"k":"macro","name":"Per Dominum"}],"LectioL1":[{"k":"text","la":"Léctio libri Deuteronómii"},{"k":"ref","la":"Deut 26:12-19"},{"k":"text","la":"In diébus illis: Locútus est Móyses ad pópulum, dicens: Quando compléveris décimam cunctárum frugum tuárum, loquéris in conspéctu Dómini, Dei tui: Abstuli, quod sanctificátum est de domo mea, et dedi illud levítæ et ádvenæ et pupíllo ac víduæ, sicut jussísti mihi: non præterívi mandáta tua, nec sum oblítus impérii tui. Obœdívi voci Dómini, Dei mei, et feci ómnia, sicut præcepísti mihi. Réspice de sanctuário tuo et de excélso cœlórum habitáculo, et benedic pópulo tuo Israël, et terræ, quam dedísti nobis, sicut jurásti pátribus nostris, terræ lacte et melle manánti. Hódie Dóminus, Deus tuus, præcépit tibi, ut fácias mandáta hæc atque judícia: et custódias et ímpleas ex toto corde tuo et ex tota ánima tua. Dóminum elegísti hódie, ut sit tibi Deus, et ámbules in viis ejus, et custódias cæremónias illíus et mandáta atque judícia, et obœ́dias ejus império. Et Dóminus elégit te hódie, ut sis ei pópulus peculiáris, sicut locútus est tibi, et custódias ómnia præcépta illíus: et fáciat te excelsiórem cunctis géntibus, quas creávit in laudem et nomen et glóriam suam: ut sis pópulus sanctus Dómini, Dei tui, sicut locútus est."},{"k":"macro","name":"Deo gratias"}],"GradualeL1":[{"k":"ref","la":"Ps 78:9; 78:10"},{"k":"text","la":"Propítius esto, Dómine, peccátis nostris: ne quando dicant gentes: Ubi est Deus eórum?"},{"k":"text","la":"Adjuva nos, Deus, salutáris noster: et propter honórem nóminis tui, Dómine, líbera nos.","mark":"V"}],"OratioL1":[{"k":"text","la":"Protéctor noster, áspice, Deus: ut, qui malórum nostrórum póndere prémimur, percépta misericórdia, líbera tibi mente famulémur."},{"k":"macro","name":"Per Dominum"}],"LectioL2":[{"k":"text","la":"Léctio libri Deuteronómii"},{"k":"ref","la":"Deut 11:22-25"},{"k":"text","la":"In diébus illis: Dixit Móyses fíliis Israël: Si custodiéritis mandáta, quæ ego præcípio vobis, et fecéritis ea, ut diligátis Dóminum, Deum vestrum, et ambulétis in ómnibus viis ejus, adhæréntes ei, dispérdet Dóminus omnes gentes istas ante fáciem vestram, et possidébitis eas, quæ majóres et fortióres vobis sunt. Omnis locus quem calcáverit pes vester, vester erit. A desérto et a Líbano, a flúmine magno Euphráte usque ad mare Occidentále, erunt términi vestri. Nullus stabit contra vos: terrórem vestrum et formídinem dabit Dóminus, Deus vester, super omnem terram, quam calcatúri estis, sicut locútus est vobis Dóminus, Deus vester."},{"k":"macro","name":"Deo gratias"}],"GradualeL2":[{"k":"ref","la":"Ps 83:10; 83:9"},{"k":"text","la":"Protéctor noster, áspice, Deus, et réspice super servos tuos."},{"k":"text","la":"Dómine, Deus virtútum, exáudi preces servórum tuórum.","mark":"V"}],"OratioL2":[{"k":"text","la":"Adésto, quǽsumus, Dómine, supplicatiónibus nostris: ut esse, te largiénte, mereámur et inter próspera húmiles, et inter advérsa secúri."},{"k":"macro","name":"Per Dominum"}],"LectioL3":[{"k":"text","la":"Léctio libri Machabæórum"},{"k":"ref","la":"2 Mach 1:23-26; 1:27"},{"k":"text","la":"In diébus illis: Oratiónem faciébant omnes sacerdótes, dum consummarétur sacrifícium, Jónatha inchoánte, céteris autem respondéntibus. Et Nehemíæ erat orátio hunc habens modum: Dómine Deus, ómnium Creátor, terríbilis et fortis, justus et miséricors, qui solus es bonus rex, solus præstans, solus justus et omnípotens et ætérnus, qui líberas Israël de omni malo, qui fecísti patres eléctos et sanctificásti eos: áccipe sacrifícium pro univérso pópulo tuo Israël, et custódi partem tuam et sanctífica: ut sciant gentes, quia tu es Deus noster."},{"k":"macro","name":"Deo gratias"}],"GradualeL3":[{"k":"ref","la":"Ps 89:13; 89:1"},{"k":"text","la":"Convértere, Dómine, aliquántulum, et deprecáre super servos tuos."},{"k":"text","la":"Dómine, refúgium factus es nobis, a generatióne et progénie.","mark":"V"}],"OratioL3":[{"k":"text","la":"Preces pópuli tui, quǽsumus, Dómine, cleménter exáudi: ut, qui juste pro peccátis nostris afflígimur, pro tui nóminis glória misericórditer liberémur."},{"k":"macro","name":"Per Dominum"}],"LectioL4":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 36:1-10"},{"k":"text","la":"Miserére nostri, Deus ómnium, et réspice nos, et osténde nobis lucem miseratiónum tuárum: et immítte timórem tuum super gentes, quæ non exquisiérunt te, ut cognóscant, quia non est Deus nisi tu, et enárrent magnália tua. Alleva manum tuam super gentes aliénas, ut vídeant poténtiam tuam. Sicut enim in conspéctu eórum sanctificátus es in nobis, sic in conspéctu nostro magnificáberis in eis, ut cognóscant te, sicut et nos cognóvimus, quóniam non est Deus præter te, Dómine. Innova signa et immúta mirabília. Glorífica manum et bráchium dextrum. Excita furórem et effúnde iram. Tolle adversárium et afflíge inimícum. Festína tempus et meménto finis, ut enárrent mirabília tua, Dómine, Deus noster."},{"k":"macro","name":"Deo gratias"}],"GradualeL4":[{"k":"ref","la":"Ps 140:2"},{"k":"text","la":"Dirigátur orátio mea sicut incénsum in conspéctu tuo, Dómine."},{"k":"text","la":"Elevátio mánuum meárum sacrifícium vespertínum.","mark":"V"}],"OratioL4":[{"k":"text","la":"Actiónes nostras, quǽsumus, Dómine, aspirándo prǽveni, et adjuvándo proséquere: ut cuncta nostra orátio et operátio a te semper incípiat, et per te cœpta finiátur."},{"k":"macro","name":"Per Dominum"}],"LectioL5":[{"k":"text","la":"Léctio Daniélis Prophétæ"},{"k":"ref","la":"Dan 3:47-51"},{"k":"text","la":"In diébus illis: Angelus Dómini descéndit cum Azaría et sóciis ejus in fornácem: et excússit flammam ignis de fornáce, et fecit médium fornácis quasi ventum roris flantem. Flamma autem effundebátur super fornácem cúbitis quadragínta novem: et erúpit, et incéndit, quos répperit juxta fornácem de Chaldǽis, minístros regis, qui eam incendébant. Et non tétigit eos omníno ignis, neque contristávit, nec quidquam moléstiæ íntulit. Tunc hi tres quasi ex uno ore laudábant, et glorificábant, et benedicébant Deum in fornáce, dicéntes:"},{"k":"sep"},{"k":"rubric","la":"Hymnus"},{"k":"ref","la":"Dan 3:52-59"},{"k":"text","la":"Benedíctus es, Dómine, Deus patrum nostrórum. Et laudábilis et gloriósus in sǽcula."},{"k":"text","la":"Et benedíctum nomen glóriæ tuæ, quod est sanctum. Et laudábile et gloriósum in sǽcula."},{"k":"text","la":"Benedíctus es in templo sancto glóriæ tuæ. Et laudábilis et gloriósus in sǽcula."},{"k":"text","la":"Benedíctus es super thronum sanctum regni tui. Et laudábilis et gloriósus in sǽcula."},{"k":"text","la":"Benedíctus es super sceptrum divinitátis tuæ. Et laudábilis et gloriósus in sǽcula."},{"k":"text","la":"Benedíctus es, qui sedes super Chérubim, íntuens abýssos. Et laudábilis et gloriósus in sǽcula."},{"k":"text","la":"Benedíctus es, qui ámbulas super pennas ventórum et super undas maris. Et laudábilis"},{"k":"text","la":"et gloriósus in sǽcula."},{"k":"text","la":"Benedícant te omnes Angeli et Sancti tui. Et laudent te et gloríficent in sǽcula."},{"k":"text","la":"Benedícant te coeli, terra, mare, et ómnia quæ in eis sunt. Et laudent te et gloríficent in sǽcula."},{"k":"text","la":"Glória Patri, et Fílio, et Spirítui Sancto. Et laudábili et glorióso in sǽcula."},{"k":"text","la":"Sicut erat in princípio, et nunc, et semper: et in sǽcula sæculórum. Amen. Et laudábilis et gloriósus in sǽcula."},{"k":"text","la":"Benedíctus es, Dómine, Deus patrum nostrórum. Et laudábilis et gloriósus in sǽcula."}],"OratioL5":[{"k":"text","la":"Deus, qui tribus púeris mitigásti flammas ígnium: concéde propítius; ut nos fámulos tuos non exúrat flamma vitiórum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"f6abfe8e6ff26f5f":{"t":"Ps 87, 3, Ps 87, 2\n(Ps 87, 3) Neka uziđe molitva moja pred lice tvoje. Prikloni uho svoje i čuj molitvu moju, Gospodine. (Ps 87, 2) Gospodine, Bože spasenja mojega, danju i noću vapijem k tebi.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 87, 3) Neka uziđe molitva moja pred lice tvoje. Prikloni uho svoje i čuj molitvu moju, Gospodine.","kn":"(Ps. 87, 3). Vinula se molitva moja pred lice Tvoje, čuj molitvu moju. Gospodine! (Ps. 87, 2) Gospodine, Bože spasenja mojega, danju i noću vapijem k Tebi. Slava Ocu . . . Vinula se . . .","knRef":"Kniewald 1942, str. 124–125 (snimka 63) (OCR)"},"4354db7856b37427":{"t":"<i>Pomolimo se</i>.\n<i>Prignimo koljena. - Ustanite</i>.\nMilostivo pogledaj, Gospodine, svoj narod, i blagostivo odvrati od njega bičeve svoje srdžbe.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"c541a9e382b8bc82":{"t":"Pnz 26, 12-19\nČitanje knjige Ponovljenog zakona. U one dane reče Mojsije narodu: Kad predaš desetinu od svojih plodova, reci Gospodinu Bogu svome: Uzeo sam iz kuće ono što je posvećeno i predao sam levitu, strancu, siroti i udovici, kako si mi zapovjedio. Nisam mimoišao tvoje zapovijedi, niti sam zaboravio tvoje naredbe. Poslušao sam glas Gospodina Boga svoga i učinio sam sve kako si mi zapovjedio. Pogledaj iz svoga svetišta i iz svoga nebeskog prebivališta i blagoslovi puk svoj Izraelov i zemlju koju si nam dao, zemlju koja teče mlijekom i medom kako si se zakleo ocima našim. Danas ti zapovijeda Gospodin Bog tvoj da vršiš njegove zapovijedi i odredbe, i da ih čuvaš i ispunjavaš svim srcem svojim i svom dušom svojom. Danas si izabrao Gospodina da ti bude Bog, da vršiš njegove odredbe, i da budeš podložan njegovoj vlasti. A Gospodin je danas izabrao tebe da mu budeš izabrani narod, kao što ti je govorio, i da vršiš sve zapovijedi njegove. On će te uzvisiti nad sve narode, koje je stvorio na svoju hvalu, čast i slavu, a ti budi sveti narod Gospodina Boga svoga, kao što ti je rekao.","kn":"Čitanje knjige Deuteronomija (26, 12-19). U one dane reče Moj sije narodu govoreći: Kad si predao desetinu od svih plodova, kaži Gospodinu Bogu svome: Uzeo sam iz kuće ono, što je posvećeno Bogu i P'redao sam leviti, strancu, siroti i udovici, kako si mi zapovjedio. Nisam mi'moišao zapovijedi Tvojih, niti sam zaboravio na ono, što si mi lialožiO'. Bio sam poslušan glasu Gospodina Boga mojega i učinio sam sve, kako si mi zapovijedi«. Pogledaj, dakle, iz svetlštai svoga i iz uzvišenog stana svoga u nebesima i blagoslovi puk svoj Izraelov, i blagoslovi zemlju, koja teče medom i mlijekom, kako si se zakleo očima našim. Danas ti je Gospodin Bog tvoj zapovjedio, da izvršiš zapovijedi njegove i odredbe iz svega srca svoga i iz sve duše svoje. Danas si izabrao Gospodina,, da ti bude Bog i da hodaš njegovim putovima, da vršiš njegove obrede, zapovijedi i odredbe i ,da budeš podložan nj egO'VO'j vlasti. I Gospodin te je izabrao danas, da mu budeš izar branim narodom, kao što ti je govorio, i da, vršiš sve zapovijedi njegove. I uzvisit će te nad sve narode, koje je stvorio, na hvalu i slavu Imena svO'ga, da budeš narod sveti Gospodina Boga svoga, kao što je rekao.","knRef":"Kniewald 1942, str. 124–125 (snimka 63) (OCR)"},"c399c7fe3a69bd10":{"t":"Ps 78, 9 i 10\nBudi milostiv, Gospodine, grijesima našim. Zašto da govore narodi: Gdje je Bog njihov? Pomozi nam, Bože spasitelju naš, i radi slave imena svoga izbavi nas, Gospodine.","kn":"(Ps. 78, 9, 10). Blag budi. Gospodine, grijesima našim, da ne kažu u narodima; gdje' je Bog njihov? Pomozi nam. Bože, spasitelju naš,~ i poradi slave imena svoga izbavi nas!","knRef":"Kniewald 1942, str. 414–415 (snimka 208) (OCR)"},"8587c9d9affe9d78":{"t":"<i>Pomolimo se</i>.\n<i>Prignimo koljena. - Ustanite</i>.\nPogledaj na nas, Bože, zaštitniče naš, da ti mi koje pritišće težina naših zala, primivši milosrđe, služimo slobodnim duhom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pomolijtio se! Prigrlite koljena! Dignite se! Pogledaj na nas, Bože, zaštitnice naš i podaj, da mi, koje pritište teret naših grijeha, primivši Tvoje milosrđe, slobodnom dušom Tebi služimo, po G. n.","knRef":"Kniewald 1942, str. 126–127 (snimka 64) (OCR)"},"968339984ef39fb3":{"t":"Pnz 11, 22-25\nČitanje knjige Ponovljenog zakona. U one dane reče Mojsije sinovima Izraelovim: Ako budete vršili zapovijedi što vam ih ja dajem, i pokazali da ljubite Gospodina Boga svoga, i išli svim njegovim putovima, i njega se držali, tada će otjerati Gospodin sve narode ispred vas i pobijedit ćete ih, premda su veći i jači od vas. Vaše će biti svako mjesto na koje stupite svojom nogom. Vaše će se granice rasprostraniti od pustinje i Libana i velike rijeke Eufrata sve do zapadnoga mora. Nitko vam se neće moći oduprijeti. Gospodin Bog vaš raširit će strah i trepet pred vama po svoj zemlji, na koju stupite, kao što vam je obećao Gospodin Bog vaš.","kn":"Čitanje knjige Deutercnomija (11, 22-25). U one dane reže Mojsije sinovima izraelskim; Budete li vršili zapovijedi, što vam ih ja dajem diamas, budete li doista ljubili Gospodina Boga svoga i budete li išli njegovim putovima, priljubivši se uza nj, raspršit će Gospodin sve narode oyei pred licem vašim i vladat ćete nad njima, premda su veći i jači od vas. Svaki će pedalj zemlje, na koji stupite nogom svojom, biti vaš. Vaše , će se granice rasprostirati od pustinje i Libainona i velike rijeke Eufrata sve do zapadnoga mora. Nitko vam se ne će moći oduprijeti. Gospodin će Bog vaš uliti svima strah i trepet pred vama po svoj zemlji, .na koju stupi noga vaša, kao^ što vam reče Gospodin Bog vaš.","knRef":"Kniewald 1942, str. 126–127 (snimka 64) (OCR)"},"f4cf2c168e71bfde":{"t":"Ps 83, 10 i 9\nBranitelju naš, pogledaj, Bože, i vidi sluge svoje. Gospodine Bože vojska, čuj molitve slugu svojih.","kn":"(Ps. 83, 10). Zaštitnice naš, Bože, pogledaj i vidi lice pomazanika, sluge svojega; Gospodine, Bože nad vojskama, usliši molitvu slugu svojih,","knRef":"Kniewald 1942, str. 380–381 (snimka 191) (OCR)"},"f96ce98fe20edd45":{"t":"<i>Pomolimo se</i>.\n<i>Prignimo koljena. - Ustanite</i>.\nBlizu budi, molimo, Gospodine, prošnjama našim, da po tvojem daru uzmognemo biti i u sreći ponizni i u nesreći sigurni.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"8dfcba2442a89755":{"t":"2 Mak 1, 23-26 i 27\nČitanje knjige Makabejaca. U one dane, dok je žrtva izgarala, Jonata je započeo molitvu, koju su svećenici nastavili, i svi ostali odgovarali. Zajedno s Nehemijom molili su ovako: Gospodine Bože, stvoritelju svega, silni i jaki, pravedni i milosrdni, jedini dobri kralju, jedini višnji, jedini pravedni, svemogući i vječni. Ti oslobađaš Izraela od svakoga zla. Ti si izabrao i posvetio naše očeve. Primi ovu žrtvu za cijeli svoj Izraelski narod! Štiti i posveti svoju baštinu, da upoznaju neznabošci da si ti Bog naš.","kn":"Čitanje knjige Makabcjaca (II, 1, 23-26, 27). U one dane rekoše svi svećenici molitvu, dok se svršavala žrtva. Jonata j© započeo, a svi su ostali od.govarali. A molitva Nehemije glasi ovako: Gospodine Bože, ^ Poganske narode u Palestini. — Kako krasna primjena ovog starozavjetnog obećanja na duhovni svijet novog zavjeta! '1 stvoritelju svega, pravedni i milosrdni, jedini dobri kralju, jedini odlični, jedini pravedni, svemogući i vječni. Ti oslobađaš Izraela od svega zla. Ti si učinio . očeve naše. svojim izabranicima i Ti si ih posvetio: prinii žrtvu u ime cijeloga puka svoga Izraela i čuvaj svoj dio i posveti ga^, da znadu neznabošci, da si Ti Bog naš.","knRef":"Kniewald 1942, str. 126–127 (snimka 64) (OCR)"},"fd13aa39174cfd01":{"t":"Ps 89, 13 i 1\nOkreni se k nama, Gospodine! Milostiv budi svojim slugama. Gospodine, ti si nam bio utočište od koljena do koljena.","kn":"(Ps. 89, 13, 1). Povrati se. Gospodine, ponešto, i budi milostiv slugama svojim. Gospodine, Ti si nam utočište od koljena do koljena.","knRef":"Kniewald 1942, str. 382–383 (snimka 192) (OCR)"},"3a495bdd3f7e4789":{"t":"<i>Pomolimo se</i>.\nMolitve puka Svojega, molimo, Gospodine, milostivo usliši da mi koji s pravom trpimo zbog svojih grijeha, milosrdno budemo spašeni na slavu tvojeg imena.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo. Te, Gospodine, usliši milostivo molitve puka svoga, da mi, .koji pravedno trpimo radi svojih grijeha, milosrdno budemo izbavljeni radi .slave imena. .Tvoga, . po, G, n. . I. K.. . .","knRef":"Kniewald 1942, str. 88–89 (snimka 45) (OCR)"},"f28e0aef3cd108d4":{"t":"Sir 36, 1-10\nČitanje knjige Mudrosti. Smiluj se nama, Bože svemira, pogledaj nas i pokaži nam svjetlo svoga milosrđa. Utisni svoj strah u srce naroda koji te ne štuju, da upoznaju kako nema Boga osim tebe, i da pripovijedaju tvoja čudesa. Podigni ruku svoju na tuđe narode da vide tvoju svemoć. Kao što si se pred njima pokazao svet prema nama, tako se nama pokaži silan prema njima, da i oni upoznaju kao i mi da nema Boga osim tebe, Gospodine. Ponovi znakove, opetuj čudesa, proslavi ruku i desnicu svoju. Pokaži gnjev i iskali srdžbu, makni protivnika i baci neprijatelja. Skrati vrijeme i sjeti se svršetka, da slave tvoja divna djela, Gospodine Bože naš.","kn":"Čitanje knjige Mudrosti (Crkv* 36, 1-10)- Smiluj se nama. Bože vasione, pogledaj, na nas i pokaži nam svijetlo miloBrđa svoga. Pošlji strah svoj nad narode, koji .ne traže tebe, da spoznaju, da nema Boga osim tebe i da pripovijedaju divna djela tvoja. Uzdigni ruku svoju nad strane narode, da vide moć tvoju. Jer. kao što si se n,a nama pokazao svetim pred njihovim očima, tako pokaži i na njima, pred našim očima, da si moćan, da te spoznaju, kao što smo. i mi spoznali, da nema Boga osim tebe. Gospodine! Obnovi čudesa i opetuj znakove, proslavi ruku svoju i desnicu svoju. Uništi protivnika i karzni neprijatelja, požuri vrijeme (izbavljenja) 1 sjeti se kraja, da propovijedaju divna djela tvoja, Gospodine, Bože na^!","knRef":"Kniewald 1942, str. 126–127 (snimka 64) (OCR)"},"4858c91658e475b9":{"t":"Ps 140, 2\nNeka se vine, Gospodine, molitva moja k tebi kao tamjan. Dizanje ruku mojih kao večernja žrtva.","kn":"(Ps. 140, 2). Vinula se, Gospodine, preda Te molitva moja kao kad tamjaoov, a dizanje ruku mojih kao žrtva večernja.","knRef":"Kniewald 1942, str. 114–115 (snimka 58) (OCR)"},"75e927bf8a5714f1":{"t":"<i>Pomolimo se</i>.\n<i>Prignimo koljena. - Ustanite</i>.\nDjela naša, molimo Gospodine, milošću svojom preteci i pomoću prati, da svaka naša molitva i radnja s tobom vazda počinje i početa da se s tobom dovrši.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Djela naša, molimo Gospodine, milošću .svojom preteci i pomoću prati, da se svaka naša molitva i Litanije Imena Isusova radnja tobom vazda počinje i početa da se s tobom dovršuje.","knRef":"Kniewald 1942, str. 918–919 (snimka 460) (OCR)"},"f3b9abeff48a1c81":{"t":"Dn 3, 47-51\nČitanje Danijela proroka. U one dane siđe anđeo Gospodnji s Azarijom i njegovim drugovima u užarenu peć. Istjerao je plamen iz peći te je usred peći bilo hladno kao da puše vjetar. A plamen se nad peć dizao četrdesetdevet lakata, izbijao je iz peći i sažegao koga je god zahvatio od Kaldejaca, kraljevih službenika. A njih se oganj nije dotakao niti ih je opario, niti ih je najmanje ozlijedio. Tada su u užarenoj peći jednoglasno zapjevali pjesmu slave i veličali Boga govoreći [Ovdje se ne odgovori Deo gratias]:","kn":"Čitanje Danijela proroka (3, 47-51). U one je dane sašao anđeo Gospodnji s Azarijom i drugovima njegovim u užarenu peć; on je tj'erao plamen iz peči i učinio je, da je usred peći bilo hladno, kao da puše vjetar. A plamen se izdizao nad peći četrdesetidevet lakata i izbio je iz peći i zapalio svakoga, koga je zahvatio od Kaldejaca, službenika kraljevih. Ali njih same nije dotakao plamen ni najmanje, niti ih oštetio ili ozlijedio. Tada zapjevaše kao jednoglasno pjesmu slave i stavljahu Bogai, u užarenoj peći govoreći: . i i i , I","knRef":"Kniewald 1942, str. 48–49 (snimka 25) (OCR)"},"23389579e540de0f":{"t":"Dn 3, 52-56\nBlagoslovljen si, Gospodine, Bože otaca naših. I dostojan hvale i slavan u vijeke. <i>\n</i>\nI blagoslovljeno sveto ime slave tvoje. I dostojno hvale i slavno u vijeke. <i>\n</i>\nBlagoslovljen si u svetom hramu slave svoje. I dostojan hvale i slavan u vijeke. <i>\n</i>\nBlagoslovljen si na svetom prijestolju kraljevstva svoga. I dostojan hvale i slavan u vijeke. <i>\n</i>\nBlagoslovljen si sa žezlom božanstva svoga. I dostojan hvale i slavan u vijeke. <i>\n</i>\nBlagoslovljen si ti koji vladaš nad kerubinima i promatraš bezdane. I dostojan hvale i slavan u vijeke. <i>\n</i>\nBlagoslovljen si ti koji ideš na krilima vjetrova i po valovima mora. I dostojan hvale i slavan u vijeke. <i>\n</i>\nNeka te blagoslivaju svi anđeli i sveti tvoji. I neka te hvale i slave u vijeke. <i>\n</i>\nNeka te blagoslivaju nebesa, zemlja, more i sve što je na njima. I neka te hvale i slave u vijeke. <i>\n</i>\nSlava Ocu i Sinu i Duhu Svetomu. Dostojnom hvale i slavnom u vijeke. <i>\n</i>\nKako bijaše u početku, tako i sada i vazda i u vijeke vjekova. Amen. Dostojnom hvale i slavnom u vijeke. <i>\n</i>\nBlagoslovljen si, Gospodine, Bože otaca naših. I dostojan hvale i slavan u vijeke."},"6073d3b7d83d95a7":{"t":"<i>Pomolimo se</i>.\nBože, koji si trojici mladića ublažio žestinu vatre, dopusti milostivo da nas sluge tvoje ne sažeže plamen opačina.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si trojici mladića ublažio žar ognjen, dopusti umllostivljen, da nas, sluge Tvoje, ne sažge plamen opačina, i>o G. n. I. K.","knRef":"Kniewald 1942, str. 50–51 (snimka 26) (OCR)"},"39f4eb91363b5ec2":{"t":"1 Sol 5, 14-23\nČitanje Poslanice bl. Pavla apostola Solunjanima. Braćo, molimo vas, opominjite nemirne, tješite malodušne, zaklonite slabe, budite strpljivi sa svima! Ne dopustite, da tko drugome vraća zlo za zlo nego uvijek nastojite oko dobra jedan prema drugome i prema svima. Radujte se uvijek, molite bez prestanka. Budite zahvalni za sve, jer ovo je Božja volja u Kristu Isusu za sve vas. Duha ne gasite! Ne zanemarujte proročkih riječi, nego sve provjerite, pa što je dobro čuvajte, a klonite se svakoga zla. A Bog mira posvetio vas i očuvao čitavo vaše biće, i dušu i tijelo, bez krivnje za dolazak Gospodina našega Isusa Krista.","kn":"Čitanje poslanice bi. Pavla apostola Solun janima (I, 5, 14). Braćo, opominjemo vas, korite neuredne, tješite malodušne, pomažite slabima, budite ustrp- Ijivi sa svima. Gledajte, da :nitko ne vraća, nikome zlo za zlo! Nego svagda revno nastojite o dobru, i među sobom, i prema svima. Radujte se svagda. Molite se bez prestanka. Na svem žahValjnjte, jer to hoće Bog od vas u Isusu krištu.. Duha, ne gasite. Proroštva nemojte prezirati. Sve kušajte', dobro zadržite. Uklanjajte se od svake prilike 'zla. A sam Boig mira da iposveti vas cijele, i cijeli\"vaš duh i dušu, i tijelo da se sačuva bez prijekora :ža dolazak Gospodina našega Isusia Krista, . ■ -","knRef":"Kniewald 1942, str. 128–129 (snimka 65) (OCR)"},"5f107e4031aa705c":{"t":"Ps 116, 1-2\nHvalite Gospodina, sva plemena, hvalite ga, svi narodi. Jer je silno nad nama milosrđe njegovo, i istina Gospodnja ostaje dovijeka.","kn":"(Ps. 116, 1, 2). Hvalite Gospodina sva plemena, hvalite ga svi narodi, jer je silno nad nama njegovo milosrđe i istina Gospodnja ostaje dovijeka.","knRef":"Kniewald 1942, str. 340–341 (snimka 171) (OCR)"},"47598764b5506c06":{"t":"Mt 17, 1-9\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: uze Isus sa sobom Petra, Jakova i njegova brata Ivana, i povede ih nasamo na visoku goru te se preobrazi pred njima. Njegovo lice zasja kao sunce, a haljine mu pobijeliše kao snijeg. I gle, ukažu im se Mojsije i Ilija razgovarajući s njim. Tada Petar reče Isusu: Gospodine, dobro nam je ovdje. Ako hoćeš, ovdje ćemo podići tri sjenice: jednu tebi, jednu Mojsiju, jednu Iliji. Dok je on još govorio, prekrije ih svijetao oblak. I gle, iz oblaka se čuo glas: Ovo je moj ljubljeni Sin koji mi je po volji, njega slušajte! – Kad su to učenici čuli, padnu ničice silno prestrašeni. Isus im pristupi, dotače ih se i reče: Ustanite i ne bojte se! Oni podignu oči i ne vidješe nikoga, osim Isusa. I dok su silazili s gore, Isus im naloži: Ne govorite nikome o viđenju, dok Sin Čovječji ne uskrsne od mrtvih.","v":"et → ∅","kn":"t Slijedi sveto evanđelje po Mateju (17, 1-9). U ono vrijeme uze Isus Petra i Jakova i njegova brata Ivana, i povede ih nasamo, na visoku goru, i preobrazi se pred njima. I lice mu zasja kao sunce, a Ponedjeljak iz.i U. nedjelje u korizmi njegove haljine postadoše bijele kao snijeg. I ukazaše im se Mojsije i Ilija govoreći s njim. Tada Petar reče: Gospodine, dobro nam je biti ovdje. Ako hoćeš, načinit ćemo tri sjenice: jednu tebi, jednu Mojsiju d jednu Iliji. Dok je on još govorio, zasjeni ih uto sjajan oblak. I glas s neba progovori: Ovo je moj ljubljeni Sin, koji mi je omilio: njega slušajte! Kad su to čuli njegovi učenici, padoše ničice i . silno se prepadoše. I pristupi im Isus, dotače ih se i reče im: Ustanite i ne bojte se! .A kad su podigli svoje oči, nijesu nikoga, vidjeli nego samo Isusa. I dok su silazili s gore, Isus im zabrani: Nikomu ne govorite o viđenju, dok Sin čovječji ne uskrsne od mrtvih.","knRef":"Kniewald 1942, str. 130–131 (snimka 66) (OCR)"},"02bd724c45b09d26":{"t":"Ps 87, 2-3\nGospodine, Bože spasenja mojega, danju i noću vapijem k tebi. Neka uziđe molitva moja pred lice tvoje, Gospodine.","kn":"(Ps. 87, 2, 3). Gospodine Bože, spasitelju moj, danju 1 noću vapijem k Tebi, vinula se molitva moja pred lice Tvoje!","knRef":"Kniewald 1942, str. 128–129 (snimka 65) (OCR)"},"71cd80d637e27e15":{"t":"Posveti, Gospodine, naše postove po ovim žrtvama da ono što naše odricanje izvana očituje iznutra proizvede.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Posveti, molimo. Gospodine, ovim žrtvama naše postove, da u našoj nutrini izvrše ono, što naša služba izražava vanjskim načinom, po G. n.","knRef":"Kniewald 1942, str. 128–129 (snimka 65) (OCR)"},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo 1 spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože. koji tjelesnim postom obuzdavaš opačine, duh dižeš, daješ krepost i nagrade,' po Kristu, Gospodinu našemu; po kojem veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti, Nebesa Te 1 nebeske Red i čin sv. mise moći i blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se s njima smiju sjediniti i naši glasovi, koji govore u smjernom ispovijedanju:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"bd355dd03feb95c8":{"t":"Ps 7, 2\nGospodine, Bože moj, u tebe se uzdam. Spasi me od svih koji me progone i izbavi me.","kn":"(Ps. 7, 2). Gospodine, Bože moj, u Tebe se uzdam, spasi me od svih, koji me progone i izbavi me!","knRef":"Kniewald 1942, str. 128–129 (snimka 65) (OCR)"},"2104d956a558a7f0":{"t":"<i>Pomolimo se</i>.\nSvemoćni Bože, neka nas tvoja posvetna otajstva iscijele od opačina i neka nam budu na vječnu pomoć.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Svemogući Bože, neka se Tvojim posvetilištima i naše opačine iscijele i vječne nam pomoći prolzlđu, po G. n.","knRef":"Kniewald 1942, str. 408–409 (snimka 205) (OCR)"},"eff1b0c9025150ec":{"t":"<i>Pomolimo se</i>.\n<i>Prignite pred Bogom svoje glave</i>.\nŽeljeni blagoslov, Bože, neka utvrdi tvoje vjerne i neka učini da se nikada ne razilaze s voljom tvojom te im dade da se uvijek raduju tvojim dobročinstvima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pomolimo se! Prignite ponizno glave svoje pred Bogom! Vjerne Tvoje, Bože, učvrstio žuđeni blagoslov, da se nikad ne udalje od Tvoje volje i da se uvijek raduju Tvojim dobročinstvima, po G. n.","knRef":"Kniewald 1942, str. 128–129 (snimka 65) (OCR)"}}});
